  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Deletion protection is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Deletion protection is disabled, which increases the risk of accidental or malicious deletion of the database instance."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Backups are disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "Backups are disabled, which means data recovery is not possible in case of data loss or corruption."
    },
    {
      "check_id": "UNKNOWN",
      "title": "SSL is not required for database connections",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "Not requiring SSL for database connections exposes data in transit to potential interception and compromise."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Lock wait logging is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Disabling lock wait logging makes it harder to troubleshoot and optimize database performance issues."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = true\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n  }\n}",
  "fix_summary": "Enabled deletion protection to prevent accidental or malicious deletion. Enabled backups to ensure data recovery is possible. Required SSL for secure database connections. Enabled lock wait logging to improve troubleshooting and performance optimization."
}
